update schedule_context set value=public.marketplace_sync_dispatch_claim((select worker_id from public.marketplace_worker_runtime),(select worker_epoch from public.marketplace_worker_runtime),gen_random_uuid(),true) where name='run';
select is((select value->>'authorizationKind' from schedule_context where name='run'),'scheduled_read','Kurzer Zeitplan startet einen freigegebenen Hintergrundabruf');
select ok((select next_due_at-last_attempt_at between interval '2 minutes 59 seconds' and interval '3 minutes 1 second' from public.marketplace_sync_schedules),'Dispatcher plant ebenfalls mit drei Minuten');
select is(public.marketplace_sync_dispatch_claim((select worker_id from public.marketplace_worker_runtime),(select worker_epoch from public.marketplace_worker_runtime),gen_random_uuid(),true),null::jsonb,'Kurzer Abstand erzeugt keinen überlappenden Browser');
select lives_ok($$select public.marketplace_apply_vinted_sync_import((select (value->>'operationId')::uuid from schedule_context where name='run'),(select (value->>'runnerId')::uuid from schedule_context where name='run'),(select (value->>'workerEpoch')::bigint from schedule_context where name='run'),(select (value->>'sessionId')::uuid from schedule_context where name='run'),pg_temp.snapshot())$$,'Kurzer Abruf wird mit denselben Rechteprüfungen importiert');
update public.marketplace_browser_sessions set state='closed',provider_stopped_at=clock_timestamp() where state='active';
select ok(public.marketplace_sync_finish((select (value->>'operationId')::uuid from schedule_context where name='run'),(select (value->>'runnerId')::uuid from schedule_context where name='run'),(select (value->>'workerEpoch')::bigint from schedule_context where name='run'),'{"state":"succeeded","errorCode":null}'),'Kurzer Abruf wird erfolgreich abgeschlossen');
select ok((select next_due_at-last_success_at between interval '2 minutes 59 seconds' and interval '3 minutes 1 second' from public.marketplace_sync_schedules),'Erfolgreicher Abschluss bewahrt den gewählten Abstand');
set local role authenticated;
select is(public.marketplace_set_sync_schedule('31000000-0000-4000-8000-000000000011','31000000-0000-4000-8000-000000000021',true,60,(select authorization_version from public.marketplace_sync_schedules))->>'intervalMinutes','60','Längerer Abstand lässt sich ebenfalls einstellen');
select is(public.marketplace_set_sync_schedule('31000000-0000-4000-8000-000000000011','31000000-0000-4000-8000-000000000021',false,60,(select authorization_version from public.marketplace_sync_schedules))->>'intervalMinutes','60','Pausieren bewahrt den eingestellten Abstand');
reset role;
select * from finish();
rollback;
